old_glow = '{/* Top Blue Glow inside card */}\n            <div className="absolute top-0 left-1/2 -translate-x-1/2 w-full h-[150px] bg-gradient-to-b from-[#006AFF]/30 to-transparent pointer-events-none" />'
new_glow = '{/* Top Blue Glow inside card */}\n            <div className="absolute inset-0 rounded-[32px] overflow-hidden pointer-events-none"><div className="absolute top-0 left-1/2 -translate-x-1/2 w-full h-[150px] bg-gradient-to-b from-[#006AFF]/30 to-transparent" /></div>'
content = content.replace(old_glow, new_glow)

